    #pragma omp parallel
    {
        #pragma omp for schedule(guided, 64)
        for (long i = 1; i < n; i++) {
            unsigned long v = (unsigned long)i;
            int s = 0;

            while (v != 1) {
                v = (v & 1) ? 3 * v + 1 : v / 2;
